{
  "root_cause": "Pikaday adds a global keydown listener that handles arrow keys to navigate the calendar regardless of which element has focus. When the calendar is visible, ArrowLeft in another input (e.g., #notes) is prevented from moving the caret, causing the space to be appended after 'Gate4' instead of inserting a space between 'Gate' and '4'.",
  "repair_strategy": "Modify pikaday's _onKeyChange handler to early‑return when the keydown event target is not the bound input field (opts.field). This preserves calendar keyboard navigation when the date field is focused while allowing normal caret movement in other inputs.",
  "edits": [
    {
      "path": "pikaday.js",
      "sha256": "662123ec9f429dee9cffaacfcf89b05ed9c3c30a78d33ecfd113e6778349cc77",
      "before": "        self._onKeyChange = function(e)
        {
            e = e || window.event;

            if (self.isVisible()) {

                switch(e.keyCode){
                    case 13:
                    case 27:
                        if (opts.field) {
                            opts.field.blur();
                        }
                        break;
                    case 37:
                        e.preventDefault();
                        self.adjustDate('subtract', 1);
                        break;
                    case 38:
                        self.adjustDate('subtract', 7);
                        break;
                    case 39:
                        self.adjustDate('add', 1);
                        break;
                    case 40:
                        self.adjustDate('add', 7);
                        break;
                }
            }
        };",
      "after": "        self._onKeyChange = function(e)
        {
            e = e || window.event;

            if (self.isVisible()) {
                // Ignore keyboard navigation if focus is not on the bound field
                if (opts.field && e.target !== opts.field) {
                    return;
                }

                switch(e.keyCode){
                    case 13:
                    case 27:
                        if (opts.field) {
                            opts.field.blur();
                        }
                        break;
                    case 37:
                        e.preventDefault();
                        self.adjustDate('subtract', 1);
                        break;
                    case 38:
                        self.adjustDate('subtract', 7);
                        break;
                    case 39:
                        self.adjustDate('add', 1);
                        break;
                    case 40:
                        self.adjustDate('add', 7);
                        break;
                }
            }
        };"
    }
  ],
  "expected_accessibility_effect": "ArrowLeft, ArrowRight, ArrowUp, and ArrowDown keys will now move the caret in the notes input when the calendar is open, allowing users to correct typos without interfering with date picker navigation.",
  "functional_risks": [
    "If the pikaday instance is bound to a non-input element, arrow keys may be incorrectly ignored.",
    "If multiple pikaday instances exist on the page, the check uses opts.field which is specific to each instance, so risk is low.",
    "Custom keyboards or assistive technology that synthesize keydown events with different targets may be affected."
  ],
  "verification_requirements": [
    "Verify that ArrowLeft/Right/Up/Down in the notes input moves the caret when the calendar is visible.",
    "Verify that ArrowLeft/Right/Up/Down in the delivery-date input still changes the selected date when the calendar is visible.",
    "Verify that Enter and Esc still close the picker and blur the field when the delivery-date input is focused.",
    "Ensure that typing and other keys continue to work normally in both inputs."
  ]
}

